const result = $input.first().json;
if (result.status !== 'succeeded' || !Array.isArray(result.items)) throw new Error('X search did not return preview items.');
const posts = result.items.map((post) => ({ id: post.tweet_id, author: post.screen_name, text: post.text, likes: post.favorites, replies: post.replies, reposts: post.retweets, created_at: post.created_at }));
return [{ json: { source: 'X public keyword search', source_count: posts.length, request_ids: [result.request_id], prompt: JSON.stringify({ keyword: $('Configure Inputs').first().json.keyword, posts }) } }];

const answer = $input.first().json.choices?.[0]?.message?.content;
if (!answer) throw new Error('The text model returned no message content.');
const evidence = $('Prepare Evidence').first().json;
return [{ json: { summary: answer, source: evidence.source, source_count: evidence.source_count, request_ids: evidence.request_ids } }];
